📋 Recommended Security Headers for next.config.js:


async headers() {
  return [
    {
      source: '/:path*',
      headers: [
        { key: 'X-DNS-Prefetch-Control', value: 'on' }, // Improves performance while being safe
        { key: 'Strict-Transport-Security', value: 'max-age=63072000; includeSubDomains; preload' }, // Enforces HTTPS
        { key: 'X-Content-Type-Options', value: 'nosniff' }, // Prevents MIME type sniffing
        { key: 'X-Frame-Options', value: 'DENY' }, // Prevents clickjacking
        { key: 'X-XSS-Protection', value: '1; mode=block' }, // Legacy XSS protection (modern browsers use CSP)
        { key: 'Referrer-Policy', value: 'strict-origin-when-cross-origin' }, // Controls referrer information
        { key: 'Permissions-Policy', value: 'camera=(), microphone=(), geolocation=()' }, // Restricts browser features
      ],
    },
  ];
}

📋 Recommended middleware.ts:


import { clerkMiddleware, createRouteMatcher } from '@clerk/nextjs/server';

const isProtectedRoute = createRouteMatcher(['/dashboard(.*)']);

export default clerkMiddleware((auth, req) => {
  if (isProtectedRoute(req)) {
    auth().protect();
  }
});

export const config = {
  matcher: ['/((?!.*\\..*|_next).*)', '/', '/(api|trpc)(.*)'],
};

